#!/dd/CMDS/bash# drop -- remove exactly what `keep' put on this disk, and nothing else.## Safety here is not carefulness, it is the receipt. For every file SYS/kept# records, drop checks the MD5 keep wrote down:##   * gone already      -- says so, moves on#   * checksum matches  -- removes it#   * CHECKSUM CHANGED  -- KEEPS IT, and tells you## That last rule is why `drop hack' cannot eat your playground, your saves or# your high scores: anything you have written to is, by definition, no longer# what keep put there.##   drop <name>...   remove the files kept for those programs#   drop -n <name>   dry run# Where is the collection? Taken from the path this script was invoked by, so# it does not matter what device it is mounted as -- /h0, /h1, /dd or# anything else. SYS/login works out its own ROOT the same way. An earlier# version hardcoded /dd/CMDS and broke the moment the collection was not /dd,# which is the whole problem this collection has to survive.SELF=${0%/CMDS/*}case $SELF in "$0"|"") SELF=/h0 ;; esacC=$SELF/CMDSTO=${KEEP_TO:-/dd}RECEIPT=$TO/SYS/keptNEW=$TO/tmp/kept$$dry=noif [ "${1:-}" = "-n" ]; then dry=yes; shift; fiif [ -z "${1:-}" ]; then echo "usage: drop [-n] <name>..."; exit 1; fiif ! $C/ls $RECEIPT > /nil 2>/nil; then echo "drop: nothing has been kept on this disk"; exit 1; fifor prog in "$@"; do  found=no  : > $NEW  while IFS="	" read -r p path size sum; do    if [ "$p" != "$prog" ]; then      echo "$p	$path	$size	$sum" >> $NEW      continue    fi    found=yes    if ! $C/ls $path > /nil 2>/nil; then      echo "drop: $path is already gone"      continue    fi    $C/md5 "$path" > $NEW.m    read m1 m2 m3 now < $NEW.m    if [ "$now" != "$sum" ]; then      echo "drop: $path has CHANGED since it was kept -- left alone"      echo "$p	$path	$size	$sum" >> $NEW      continue    fi    if [ "$dry" = yes ]; then      echo "would remove $path"      echo "$p	$path	$size	$sum" >> $NEW    else      $C/rm "$path" && echo "dropped $path"    fi  done < "$RECEIPT"  if [ "$found" = no ]; then echo "drop: '$prog' was never kept here"; fi  if [ "$dry" = no ]; then $C/cp $NEW "$RECEIPT"; fidone$C/rm $NEW $NEW.m > /nil 2>/nil